pub fn collect_tap_handlers(
    root: &Node,
    out: &mut BTreeMap<u32, Rc<RefCell<dyn FnMut() + 'static>>>,
) {
    for gesture in &root.gestures {
        if let Gesture::Tap(handler) = gesture {
            out.insert(root.id, handler.clone());
        }
    }
