    pub style: u8,
    /// A two-way boolean binding (writes back on `VALUE_CHANGED`).
    pub binding: Option<WritableSignal<bool>>,
}

impl ToggleConfig {
    pub fn style(&mut self, style: u8) -> &mut Self { self.style = style; self }
    /// Bind the checked state to a signal (two-way).
