    match self {
        SignalValue::F32(f) => Some(f.to_bits()),
        SignalValue::U32(u) => Some(*u),
        SignalValue::Bool(b) => Some(if *b { 1.0f32 } else { 0.0f32 }.to_bits()),
        SignalValue::Enum(e) => Some((*e as f32).to_bits()),
        SignalValue::Str(_) => None,
    }
}

