//! Cross-platform persisted state.
use alloc::collections::BTreeMap;
use alloc::rc::Rc;
use alloc::string::String;
use alloc::format;
use core::cell::RefCell;

use pathland_engine::{Runtime, SignalId, SignalValue, SignalValueKind, WritableSignal};

pub trait StateStore {
    fn get(&self, key: &str) -> Option<SignalValue>;
    fn set(&self, key: &str, value: SignalValue);
}

#[derive(Default)]
pub struct InMemoryStateStore {
    map: RefCell<BTreeMap<String, SignalValue>>,
}
impl InMemoryStateStore { pub fn new() -> Self { Self::default() } }
impl StateStore for InMemoryStateStore {
    fn get(&self, key: &str) -> Option<SignalValue> { self.map.borrow().get(key).cloned() }
    fn set(&self, key: &str, value: SignalValue) { self.map.borrow_mut().insert(String::from(key), value); }
}

pub struct State<T> { signal: WritableSignal<T> }
impl<T: SignalValueKind> State<T> {
    pub fn get(&self) -> Option<T> { self.signal.get() }
    pub fn set(&self, value: T) -> Vec<SignalId> { self.signal.set(value) }
    pub fn update(&self, f: impl FnOnce(T) -> T) {
        if let Some(v) = self.get() { self.signal.set(f(v)); }
    }
    pub fn signal(&self) -> WritableSignal<T> { self.signal.clone() }
}

pub struct PersistentState {
    store: Rc<dyn StateStore>,
    scope: String,
    runtime: Runtime,
}
impl PersistentState {
    pub fn new(store: Rc<dyn StateStore>, scope: impl Into<String>, runtime: Runtime) -> Self {
        Self { store, scope: scope.into(), runtime }
    }
    pub fn state<T: SignalValueKind + 'static>(&self, name: &str, initial: T) -> State<T> {
        let key = format!("{}:{}", name, self.scope);
        let value = self.store.get(&key).unwrap_or_else(|| initial.into_signal_value());
        let id = self.runtime.create(value);
        let signal = WritableSignal::from_id(id, &self.runtime);
        // auto-save on change
