```java
package dev.pathland.server.proxy;

import java.io.ByteArrayOutputStream;
import java.net.URI;
import java.net.http.HttpClient;
import java.net.http.WebSocket;
import java.nio.ByteBuffer;
import java.util.Map;
import java.util.concurrent.CompletionStage;

public final class JdkWebSocketTransport implements ProxyTransport {
    private final HttpClient http;
    private volatile WebSocket ws;

    public JdkWebSocketTransport() {
        this(HttpClient.newBuilder().connectTimeout(Duration.ofSeconds(10)).build());
    }
    public JdkWebSocketTransport(HttpClient http) { this.http = http; }

    @Override
    public void connect(URI uri, Map<String,String> headers, Listener listener) {
        WebSocket.Builder builder = http.newWebSocketBuilder();
        headers.forEach(builder::header);
        builder.buildAsync(uri, new Handler(listener)).whenComplete((socket, error) -> {
            if (error != null) {
                listener.onError(error);
            } else {
                ws = socket;
                listener.onOpen();
            }
        });
    }

    @Override public void send(byte[] bytes) {
        WebSocket socket = ws;
        if (socket != null) socket.sendBinary(ByteBuffer.wrap(bytes), true);
    }

    @Override public boolean isOpen() { WebSocket s = ws; return s != null && !s.isOutputClosed(); }

    @Override public void close() {
        WebSocket socket = ws;
        ws = null;
        if (socket != null) socket.sendClose(WebSocket.NORMAL_CLOSURE, "bye");
    }

    private static final class Handler implements WebSocket.Listener {
        private final Listener listener;
        private final ByteArrayOutputStream buffer = new ByteArrayOutputStream();
        Handler(Listener l) { this.listener = l; }
        @Override public void onOpen(WebSocket webSocket) { webSocket.request(1); }
        @Override public CompletionStage<?> onBinary(WebSocket webSocket, ByteBuffer data, boolean last) {
            byte[] chunk = new byte[data.remaining()];
            data.get(chunk);
            buffer.writeBytes(chunk);
            if (last) {
                byte[] message = buffer.toByteArray();
                buffer.reset();
                listener.onBinary(message);
            }
            webSocket.request(1);
            return null;
