    static ProtocolFrame merge(ProtocolFrame base, List<ProtocolFrame> extras) {
        if (extras.isEmpty()) return base;
        List<Opcode> opcodes = new ArrayList<>(base.opcodes());
        ByteArrayOutputStream strings = new ByteArrayOutputStream();
        strings.writeBytes(base.strings());
        for (ProtocolFrame extra : extras) {
            if (extra == null || extra.isEmpty()) continue;
            int offset = strings.size();
            for (Opcode op : extra.opcodes()) opcodes.add(FrameRebase.rebase(op, offset));
            strings.writeBytes(extra.strings());
        }
        return new ProtocolFrame(opcodes, strings.toByteArray());
    }
}
