private void resolveControllers(PathlandNode scanRoot, PathlandNode owner, List<Runnable> ops) {
    List<PathlandNode> nodes = flatten(scanRoot);
    // An attach marker (`MediaController.attach()`) *is* the controller node: it
    // becomes the MEDIA_CONTROLLER in place (no structural change), so the
    // controller lives exactly where the application placed it — outside any
    // swapping branch.
    for (PathlandNode node : nodes) {
        MediaController controller = node.mediaControllerRef;
        if (controller != null && node.component == Components.COMMENT) {
            node.component = Components.MEDIA_CONTROLLER;
            applyController(node, controller);
            mediaControllers.put(controller, node);
        }
    }
    // Fallback: a `VIDEO` surface referencing a controller with no attach marker
    // (e.g. a pure-video view) — materialize the controller at the root.
    List<PathlandNode> created = new ArrayList<>();
    for (PathlandNode node : nodes) {
        MediaController controller = node.mediaControllerRef;
        if (controller == null) {
            continue;
