        let delta: std::vec::Vec<_> = frames[1].opcodes().collect();
        assert_eq!(delta.len(), 1, "one opcode: the changed source property");
        assert_eq!(delta[0].props().unwrap().property_id, property_id::MEDIA_SOURCE);
        assert_eq!(delta[0].props().unwrap().value_type, value_type::STRING);
    }
}
